// Owner question set 2 (V1.15), part F: microservices architecture and patterns, SQL/NoSQL and database concepts.
import { kp, Q } from './kp.js';

const MS = 'Microservices', DB = 'Databases & SQL';
const src = { source: 'owner-set2' };

export const V115_F = [
  // ---------------------------------------------------------------- 17. Microservices architecture and design patterns
  Q('nq-217', MS, 'E', 'concept', 'What are microservices?',
    [kp('Small, independently deployable services around business capabilities', 'independently deploy*', 'business capabilit*', 'small'), kp('Each owns its data (database per service)', 'own* its data', 'database per service', 'own database'), kp('Communicate over network APIs or messaging', 'api*', 'messag*', 'network'), kp('Decentralised teams and technology; trade-off: distributed complexity', 'team*', 'distributed', 'complexity')],
    'Microservices is an architectural style where an application is built as a set of small services, each focused on one business capability, such as orders, payments or inventory, running in its own process and deployable independently. Each service owns its data, with its own database or schema, and communicates with others through well-defined APIs, REST or gRPC, or asynchronous messages over Kafka. Small teams can own a service end to end and choose suitable technology. The price is distributed system complexity: network failures, data consistency across services, observability and operations, so it pays off mainly for large systems and organisations.',
    'When would you not recommend microservices?', src),
  Q('nq-218', MS, 'EM', 'concept', 'What are the benefits of breaking a monolithic application into microservices?',
    [kp('Independent deployment and faster releases', 'independent deploy*', 'faster release*', 'deploy independently'), kp('Independent scaling of hot services', 'scal*'), kp('Fault isolation', 'fault isolation', 'isolat*', 'failure'), kp('Team autonomy and technology choice', 'team autonomy', 'autonom*', 'technology'), kp('Costs: complexity, data consistency, operations', 'complexity', 'consistency', 'operation*', 'trade off', 'trade-off')],
    'Breaking a large monolith apart lets each service be built, tested and deployed independently, so teams release more often with smaller, less risky changes. You can scale only the parts under load, for example search or checkout, instead of the whole application. Failures are better isolated: a bug in recommendations need not take down payments, given proper timeouts and circuit breakers. Teams own services end to end and can choose technology and upgrade at their own pace, and codebases stay smaller and easier to understand. The trade-offs are real: network calls, eventual consistency, distributed tracing, more infrastructure and DevOps maturity, so the split should follow clear domain boundaries.',
    'What signs show a monolith is ready to be split?', src),
  Q('nq-219', MS, 'M', 'concept', 'How does microservices architecture support independent deployment and scalability?',
    [kp('Each service has its own build, pipeline and artifact/image', 'own pipeline', 'own build', 'artifact', 'image'), kp('Loose coupling via stable, versioned APIs and backward compatibility', 'loose* coupl*', 'versioned', 'backward compat*', 'contract'), kp('Horizontal scaling per service (replicas, autoscaling)', 'horizontal', 'replica*', 'autoscal*', 'hpa'), kp('Stateless services, own data stores', 'stateless', 'own data', 'database per service'), kp('Deployment strategies: blue-green, canary, rolling', 'blue green', 'canary', 'rolling')],
    'Each service lives in its own repository or module with its own CI/CD pipeline, producing its own container image, so it can be released without redeploying others, as long as its API contracts stay backward compatible, through versioning and tolerant readers, and are verified by contract tests. Because services are stateless and own their data, you scale them horizontally and independently: run ten replicas of the catalogue service and two of the admin service, with Kubernetes HorizontalPodAutoscaler reacting to CPU or custom metrics. Releases use rolling, blue-green or canary deployments per service, and feature flags decouple deployment from release.',
    'What breaks independent deployment in practice?', src),
  Q('nq-220', MS, 'EM', 'concept', 'How do microservices communicate with one another?',
    [kp('Synchronous: REST/HTTP, gRPC', 'rest', 'http', 'grpc', 'synchronous'), kp('Asynchronous: messaging/events via Kafka, RabbitMQ, SQS', 'kafka', 'rabbitmq', 'sqs', 'asynchronous', 'event*'), kp('Service discovery / load balancing', 'service discovery', 'load balanc*'), kp('Resilience: timeouts, retries, circuit breakers', 'timeout*', 'retr*', 'circuit breaker*'), kp('Contracts/schemas: OpenAPI, Avro, schema registry', 'openapi', 'avro', 'schema')],
    'Two styles. Synchronous request-response, where the caller waits: REST over HTTP with JSON, common for queries, or gRPC with Protocol Buffers for fast internal calls; clients find instances through service discovery or Kubernetes DNS with load balancing. And asynchronous messaging, where a service publishes events or commands to a broker such as Kafka, RabbitMQ or SQS and others consume them later, decoupling services in time and availability, which suits workflows and notifications like OrderPlaced. Synchronous calls need timeouts, retries with backoff and circuit breakers, for example Resilience4j. Both need clear contracts: OpenAPI for REST, schemas with a registry for events.',
    'How would you choose between REST and Kafka for a given interaction?', src),
  Q('nq-221', MS, 'M', 'concept', 'What is the difference between synchronous and asynchronous communication?',
    [kp('Synchronous: caller waits for the response (REST/gRPC)', 'wait*', 'block*', 'response'), kp('Asynchronous: caller sends a message and continues (events/queues)', 'continue*', 'message', 'queue', 'fire and forget'), kp('Temporal coupling/availability: sync fails if callee down', 'temporal coupling', 'available', 'down', 'cascad*'), kp('Async gives eventual consistency, needs idempotency and retries', 'eventual consistency', 'idempot*', 'retr*'), kp('Choose: queries and immediate answers vs workflows/notifications', 'query', 'immediate', 'workflow*', 'notification*')],
    'In synchronous communication the caller sends a request and waits for the answer, as with REST or gRPC. It is simple and gives an immediate result, but it creates temporal coupling: if the callee is slow or down, the caller is too, and long call chains add latency and cascading failures. In asynchronous communication the caller publishes a message or event to a broker and continues; consumers process it when they can. That decouples services, absorbs load spikes and keeps working when a consumer is down, but you accept eventual consistency, need idempotent consumers, retries, dead-letter queues and tracing across events. Use sync for queries a user is waiting on, async for workflows, integration and notifications.',
    'How do you return a result to a user for an asynchronous operation?', { ...src, sameAs: 'jb-219' }),
  Q('nq-222', MS, 'M', 'concept', 'What are RestTemplate and WebClient, and when would you use each?',
    [kp('RestTemplate: synchronous, blocking client, maintenance mode', 'resttemplate', 'synchronous', 'blocking', 'maintenance'), kp('WebClient: non-blocking, reactive (WebFlux), fluent API', 'webclient', 'non blocking', 'non-blocking', 'reactive'), kp('WebClient for many concurrent calls / reactive apps; can block too', 'concurrent', 'reactive', 'block()'), kp('Newer: RestClient (Spring 6.1) and HTTP interfaces; Feign', 'restclient', 'http interface*', 'feign'), kp('Configure timeouts and connection pools', 'timeout*', 'connection pool')],
    'RestTemplate is the classic synchronous HTTP client: each call blocks the thread until the response arrives, which is simple and fine for traditional servlet apps, but it is in maintenance mode. WebClient, from Spring WebFlux, is non-blocking and reactive with a fluent API: it returns Mono or Flux, can run many concurrent calls on few threads, and fits reactive applications or fan-out to several services, though you can also call block in a servlet app. For new blocking code, Spring 6.1 added RestClient, a modern fluent synchronous client, and declarative HTTP interfaces, similar to OpenFeign. Whatever the client, always configure connect and read timeouts and connection pooling.',
    'What happens if you forget to set timeouts on an HTTP client?', src),
  Q('nq-223', MS, 'EM', 'concept', 'What is an API Gateway, and why is it used?',
    [kp('Single entry point for clients in front of services', 'single entry', 'entry point', 'front'), kp('Routing and composition', 'rout*', 'aggregat*', 'compos*'), kp('Cross-cutting: auth, rate limiting, SSL termination, CORS, logging', 'authenticat*', 'rate limit*', 'ssl', 'tls', 'cors', 'logging'), kp('Hides internal topology; versioning', 'hide*', 'internal', 'version*'), kp('Examples: Spring Cloud Gateway, Kong, AWS/Azure API gateways', 'spring cloud gateway', 'kong', 'apigee', 'api management')],
    'An API gateway is the single entry point for external clients, sitting in front of the microservices. It routes requests, such as /api/orders to the order service, so clients do not need to know internal addresses or how services are split, and it can aggregate several calls into one response, the backend-for-frontend idea. It also centralises cross-cutting concerns: TLS termination, token validation, rate limiting and quotas, CORS, request size limits, caching, request logging and correlation ids, and canary routing. Examples are Spring Cloud Gateway, Kong, NGINX, AWS API Gateway and Azure API Management. It must be highly available and kept free of business logic.',
    'What is the Backend-for-Frontend pattern?', src),
  Q('nq-224', MS, 'M', 'concept', 'What is service discovery?',
    [kp('Mechanism to find network locations of service instances dynamically', 'dynamic*', 'network location*', 'instances'), kp('Service registry where instances register and send heartbeats', 'registry', 'register*', 'heartbeat*'), kp('Client-side (Eureka + load balancer) vs server-side (load balancer/K8s Service)', 'client side', 'client-side', 'server side', 'server-side'), kp('Kubernetes DNS and Services, Consul', 'kubernetes', 'dns', 'consul')],
    'In microservices, instances start, stop and move constantly, so hard-coded addresses do not work. Service discovery lets a client find the current healthy instances of a service by name. Instances register themselves in a service registry, with their address and port, and keep sending heartbeats; dead ones are removed. In client-side discovery, the client queries the registry, such as Eureka or Consul, and load-balances itself with Spring Cloud LoadBalancer. In server-side discovery, the client calls a stable address and a load balancer or the platform routes it: in Kubernetes, a Service with a DNS name, like http://orders, does this, so Eureka is usually unnecessary there.',
    'Why is Eureka often not needed on Kubernetes?', src),
  Q('nq-225', MS, 'M', 'concept', 'What is Eureka, and how does it support service discovery?',
    [kp('Netflix OSS service registry used with Spring Cloud', 'netflix', 'registry', 'spring cloud'), kp('Eureka server; clients register on startup and send heartbeats (30s)', 'eureka server', 'register', 'heartbeat*', 'renew*'), kp('Clients cache the registry and load-balance (@LoadBalanced, lb://)', 'cache', '@loadbalanced', 'lb://', 'load balanc*'), kp('Self-preservation mode; AP design favouring availability', 'self preservation', 'self-preservation', 'availability', 'ap')],
    'Eureka is a service registry from Netflix, integrated in Spring Cloud Netflix. You run a Eureka server, a Spring Boot app with @EnableEurekaServer, usually several replicas. Each microservice with the Eureka client registers on startup with its application name, host and port, and sends a heartbeat every thirty seconds; instances that stop renewing are evicted. Clients fetch and cache the registry, so a RestTemplate or WebClient marked @LoadBalanced can call http://order-service, and Spring Cloud LoadBalancer picks an instance. Eureka favours availability: during network problems it enters self-preservation mode and stops evicting instances, accepting possibly stale entries rather than dropping everything.',
    'What is Eureka self-preservation mode and why does it exist?', src),
  Q('nq-226', MS, 'MS', 'concept', 'What is the Saga pattern?',
    [kp('Manages a business transaction across services as a sequence of local transactions', 'sequence', 'local transaction*', 'across services'), kp('Each step publishes an event/command triggering the next', 'event*', 'next step', 'trigger*'), kp('Compensating transactions undo completed steps on failure', 'compensat*', 'undo', 'rollback'), kp('Orchestration vs choreography', 'orchestrat*', 'choreograph*'), kp('Eventual consistency instead of 2PC', 'eventual consistency', '2pc', 'two phase commit', 'distributed transaction*')],
    'A saga manages a business transaction that spans several services, each with its own database, without a distributed two-phase commit. It is a sequence of local transactions: order service creates a pending order, payment service charges the card, inventory reserves stock, shipping schedules delivery. Each step commits locally and triggers the next through an event or command. If a step fails, the saga runs compensating transactions for the steps already done, such as refund the payment and cancel the order, because you cannot roll back committed work. Sagas are coordinated either by orchestration or by choreography, and they give eventual consistency, so intermediate states must be visible and acceptable, like order status PENDING.',
    'Why is two-phase commit avoided across microservices?', src),
  Q('nq-227', MS, 'SL', 'concept', 'What is the difference between Saga orchestration and choreography?',
    [kp('Orchestration: central orchestrator sends commands and tracks state', 'orchestrator', 'central', 'command*', 'tracks state'), kp('Choreography: services react to each other events, no central controller', 'react', 'events', 'no central', 'decentral*'), kp('Choreography simple for few steps but hard to follow; risk of cyclic dependencies', 'hard to follow', 'few steps', 'cyclic', 'visibility'), kp('Orchestration clearer flow and error handling, but central component', 'clear*', 'single point', 'coupling'), kp('Tools: Camunda, Temporal, Axon, AWS Step Functions', 'camunda', 'temporal', 'step functions', 'axon')],
    'In orchestration a dedicated orchestrator, which may be a service or a workflow engine such as Camunda, Temporal or AWS Step Functions, holds the saga state and tells each participant what to do: send ChargePayment, wait for the reply, send ReserveStock, and on failure send the compensating commands. The flow is explicit in one place, easy to monitor and change, but the orchestrator is a central component that knows all participants. In choreography there is no coordinator: each service listens to events and reacts, OrderCreated triggers payment, PaymentCompleted triggers inventory. It is loosely coupled and simple for a few steps, but the overall flow is implicit and spread across services, harder to understand and debug, and can create cyclic event dependencies. I use choreography for short flows, orchestration for longer business processes.',
    'How would you monitor a choreographed saga in production?', src),
  Q('nq-228', MS, 'M', 'concept', 'How does event-driven choreography work?',
    [kp('Services publish domain events after local state changes', 'publish*', 'domain event*', 'after'), kp('Other services subscribe and react with their own local transactions', 'subscribe', 'react', 'consume*'), kp('Broker like Kafka decouples producers/consumers', 'kafka', 'broker', 'topic*'), kp('Failure events trigger compensation', 'failure event*', 'compensat*', 'failed'), kp('Needs idempotent consumers, outbox, correlation ids, tracing', 'idempot*', 'outbox', 'correlation', 'tracing')],
    'Each service does its local work and then publishes a domain event describing what happened, for example OrderCreated, to a broker such as Kafka. Interested services subscribe: payment consumes OrderCreated, charges the customer and publishes PaymentCompleted or PaymentFailed; inventory reacts to PaymentCompleted by reserving stock and publishes StockReserved; the order service listens to the outcome events to update the order status. Failure events trigger compensations, like the order service cancelling the order on PaymentFailed. No service calls the others directly. To make it reliable, events are published with the outbox pattern, consumers are idempotent because messages can be redelivered, and a correlation id such as the order id lets you trace the whole flow.',
    'What happens if the same event is delivered twice?', src),
  Q('nq-229', MS, 'MS', 'concept', 'What is the Strangler Fig pattern, and how does it support incremental monolith migration?',
    [kp('Gradually replace parts of a legacy system with new services', 'gradual*', 'incremental*', 'replace'), kp('Facade/proxy/gateway routes traffic between old and new', 'facade', 'proxy', 'gateway', 'rout*'), kp('Migrate one capability at a time, then retire old code', 'one capability', 'one at a time', 'retire', 'decommission'), kp('Low risk: rollback by routing, both run in parallel', 'risk', 'rollback', 'parallel'), kp('Data migration/sync challenges (CDC, anti-corruption layer)', 'data', 'cdc', 'change data capture', 'anti corruption', 'anti-corruption')],
    'Named after a fig that grows around a tree and eventually replaces it, the Strangler Fig pattern migrates a monolith incrementally instead of a big-bang rewrite. You put a routing layer, an API gateway or proxy, in front of the monolith. Then you pick one capability, ideally with clear boundaries and high value, such as notifications or product catalogue, build it as a new service, and switch the routes for that functionality to the new service, while everything else still goes to the monolith. Repeat capability by capability, and remove the dead code from the monolith until it can be retired. It reduces risk because you can route back if problems occur. The hard parts are data: syncing or splitting the shared database, often with change data capture and an anti-corruption layer.',
    'Which capability would you extract first, and why?', src),
  Q('nq-230', MS, 'MS', 'concept', 'What is the Outbox pattern?',
    [kp('Write the event to an outbox table in the same DB transaction as the business change', 'outbox table', 'same transaction', 'same database'), kp('Separate relay publishes outbox rows to the broker', 'relay', 'poll*', 'publish*', 'message relay'), kp('Solves dual-write problem', 'dual write', 'dual-write', 'atomic*', 'cannot share a transaction', 'never out of sync'), kp('CDC (Debezium) or polling publisher', 'debezium', 'cdc', 'change data capture', 'polling'), kp('At-least-once delivery; consumers must be idempotent', 'at least once', 'at-least-once', 'idempot*')],
    'The outbox pattern guarantees that a database change and the event announcing it are never out of sync. Instead of saving the order and then sending a Kafka message, two separate systems that cannot share a transaction, the service inserts the order and an OutboxEvent row, with type, aggregate id and payload, into an outbox table in the same local database transaction. Either both are committed or neither. A separate relay then reads new outbox rows, by polling or by change data capture with Debezium reading the database log, publishes them to the broker and marks them as sent. Delivery is at least once, since the relay may publish a row twice after a crash, so consumers must be idempotent.',
    'How do you keep the outbox table from growing forever?', src),
  Q('nq-231', MS, 'SL', 'concept', 'How does the Outbox pattern maintain consistency between database updates and event publishing?',
    [kp('Single local ACID transaction covers business data and event row', 'single', 'local transaction', 'acid', 'atomic*'), kp('Publishing happens after commit, asynchronously, with retries until success', 'after commit', 'retr*', 'until success'), kp('Ordering per aggregate preserved (partition key)', 'order*', 'partition key', 'aggregate id'), kp('Idempotent consumers / dedupe by event id', 'idempot*', 'dedup*', 'event id'), kp('Eventual consistency between services', 'eventual consistency')],
    'It turns a dual write into a single write. The business update and the outbox event row are committed atomically in one local ACID transaction, so if the transaction rolls back, no event exists, and if it commits, the event is durably stored. Publishing becomes a separate, retryable step: the relay keeps trying until the broker acknowledges, and only then marks the row as published, so a broker outage only delays events instead of losing them. If the relay crashes after publishing but before marking, the event is sent again, so consumers deduplicate by event id or are naturally idempotent. Using the aggregate id as the Kafka key keeps events for one order in order. The overall result is reliable eventual consistency across services.',
    'Why is publishing to Kafka inside the @Transactional method not enough?', src),
  Q('nq-232', MS, 'SL', 'scenario', 'What happens if a database transaction succeeds but event publishing fails?',
    [kp('Dual-write problem: data saved but other services never notified', 'dual write', 'dual-write', 'never notified', 'lost event'), kp('Inconsistent system state, e.g. order saved but no payment triggered', 'inconsistent', 'stuck', 'order'), kp('Fix with outbox / transactional messaging / CDC', 'outbox', 'cdc', 'debezium'), kp('Alternatively event sourcing or listen-to-yourself; retries and reconciliation jobs', 'event sourcing', 'listen to yourself', 'reconcil*', 'retr*')],
    'This is the dual-write problem. The order is saved and committed, but the OrderCreated message never reaches Kafka, perhaps because the broker was down or the pod crashed right after commit. Downstream services never learn about the order: payment is not taken, stock is not reserved, and the order stays pending forever, an inconsistent state that is hard to detect. Retrying in memory helps only until the process dies. The robust fix is the transactional outbox, or change data capture with Debezium, so the event is stored atomically with the data and published reliably later. Other options are event sourcing, where the event is the record, and a reconciliation job that finds stuck orders and republishes or alerts.',
    'And what if the event is published but the transaction rolls back?', src),
  Q('nq-233', MS, 'SL', 'design', 'How would you prevent inconsistent states during distributed transactions?',
    [kp('Avoid 2PC; use sagas with compensations', 'saga*', 'compensat*', 'avoid 2pc', 'two phase'), kp('Outbox/CDC for reliable events', 'outbox', 'cdc'), kp('Idempotency keys and deduplication', 'idempot*', 'dedup*'), kp('Explicit intermediate states (PENDING) and timeouts', 'pending', 'state machine', 'intermediate', 'timeout*'), kp('Reconciliation, monitoring and design boundaries to minimise cross-service transactions', 'reconcil*', 'monitor*', 'boundar*')],
    'First, design service boundaries so most business invariants live inside one service and one local transaction, minimising cross-service transactions. Where they are unavoidable, I use a saga: each step is a local transaction, failures trigger compensating actions, and the process is modelled as an explicit state machine with intermediate states like PENDING_PAYMENT, plus timeouts for steps that never answer. Events are published reliably with the transactional outbox or CDC. Every handler is idempotent, using idempotency keys or processed-message tables, because messages and retries will be duplicated. Finally, I add observability with correlation ids and dashboards of stuck sagas, and reconciliation jobs that detect and repair inconsistencies, accepting eventual consistency rather than chasing distributed locks.',
    'How would you design idempotency for a payment API?', src),
  Q('nq-234', MS, 'SL', 'design', 'How would you design reliable communication between multiple downstream systems?',
    [kp('Timeouts, retries with exponential backoff and jitter', 'timeout*', 'retr*', 'backoff', 'jitter'), kp('Circuit breakers and bulkheads (Resilience4j)', 'circuit breaker*', 'bulkhead*', 'resilience4j'), kp('Asynchronous messaging with durable queues, DLQ', 'queue*', 'dead letter', 'dlq', 'durable', 'kafka'), kp('Idempotency and correlation ids; outbox', 'idempot*', 'correlation id*', 'outbox'), kp('Fallbacks, monitoring/alerting, contract tests', 'fallback*', 'monitor*', 'alert*', 'contract test*')],
    'I start by deciding which calls must be synchronous; anything that can wait goes through durable messaging, Kafka or a queue, so a slow downstream system does not block us, with dead-letter queues for poison messages and replay. For synchronous calls, every client has connect and read timeouts, retries only for idempotent or idempotency-keyed operations with exponential backoff and jitter, circuit breakers to fail fast when a system is down, and bulkheads, separate pools, so one slow dependency cannot exhaust all threads, all with Resilience4j. Responses have fallbacks where possible, such as cached data. Events are published via the outbox, every message carries a correlation id, and I monitor latency, error rates and queue lag with alerts, and protect contracts with consumer-driven contract tests.',
    'Which operations would you never retry automatically?', src),

  // ---------------------------------------------------------------- 18. SQL, NoSQL and database concepts
  Q('nq-235', DB, 'E', 'concept', 'What is the difference between SQL and NoSQL databases?',
    [kp('SQL: relational tables, fixed schema, SQL queries, joins', 'relational', 'table*', 'schema', 'join*'), kp('NoSQL: document, key-value, wide-column, graph; flexible schema', 'document', 'key value', 'key-value', 'wide column', 'graph', 'flexible'), kp('ACID transactions vs often eventual consistency (BASE)', 'acid', 'eventual', 'base'), kp('Vertical vs horizontal scaling', 'vertical', 'horizontal', 'scal*'), kp('Choose by data model and access pattern', 'access pattern*', 'use case', 'data model')],
    'SQL, relational databases such as PostgreSQL, MySQL and Oracle, store data in tables with a predefined schema and relationships enforced by foreign keys, are queried with SQL including joins and aggregations, and provide strong ACID transactions; they traditionally scale vertically, with read replicas. NoSQL is a family of non-relational stores: document databases like MongoDB, key-value stores like Redis and DynamoDB, wide-column stores like Cassandra, and graph databases like Neo4j. They have flexible schemas, are designed to scale horizontally across many nodes, and often favour availability and eventual consistency, though many now support transactions. Choose relational for complex relationships and consistency, NoSQL for huge scale, flexible structures or simple key-based access patterns.',
    'Can you give a use case where you would choose each?', src),
  Q('nq-236', DB, 'E', 'concept', 'What is the difference between relational databases and MongoDB?',
    [kp('MongoDB stores JSON-like BSON documents in collections', 'bson', 'document*', 'collection*', 'json'), kp('Relational: rows in tables with schema and joins', 'rows', 'tables', 'join*'), kp('Embedding vs normalising related data; $lookup', 'embed*', '$lookup', 'denormali*'), kp('Horizontal scaling with sharding and replica sets', 'shard*', 'replica set*'), kp('Multi-document transactions supported but modelling differs', 'transaction*', 'multi document', 'multi-document')],
    'A relational database stores rows in tables with a fixed schema, normalises related data into separate tables and joins them at query time, with strong ACID transactions and SQL. MongoDB stores JSON-like BSON documents in collections; each document can have a different structure and can embed related data, like an order with its line items in one document, so a typical read fetches everything in one go without joins. Querying uses the Mongo query language and aggregation pipelines, with $lookup for occasional joins. It scales out with sharding and replica sets for availability. It supports multi-document transactions since 4.0, but the main design rule is to model documents around access patterns.',
    'When would you embed versus reference in MongoDB?', src),
  Q('nq-237', DB, 'E', 'concept', 'What are the ACID properties of relational databases?',
    [kp('Atomicity: all or nothing', 'atomicity', 'all or nothing'), kp('Consistency: valid state, constraints hold', 'consistency', 'constraint*', 'valid state'), kp('Isolation: concurrent transactions do not interfere (isolation levels)', 'isolation', 'concurren*', 'isolation level*'), kp('Durability: committed data survives crashes (WAL)', 'durability', 'survive*', 'crash', 'write ahead log', 'wal')],
    'ACID describes reliable transactions. Atomicity: all operations in a transaction succeed or none do, so a transfer never debits without crediting. Consistency: a transaction moves the database from one valid state to another, respecting constraints, foreign keys and rules. Isolation: concurrent transactions do not see each other intermediate changes, controlled by isolation levels such as read committed, repeatable read and serializable, which trade correctness for concurrency. Durability: once committed, data survives crashes and power loss, usually guaranteed by the write-ahead log flushed to disk.',
    'Which anomalies does each isolation level prevent?', src),
  Q('nq-238', DB, 'M', 'concept', 'What is the CAP theorem?',
    [kp('Distributed system can guarantee only two of Consistency, Availability, Partition tolerance during a partition', 'two of', 'consistency', 'availability', 'partition tolerance'), kp('Partitions are unavoidable, so choose C or A during a partition', 'partition*', 'choose', 'unavoidable'), kp('CP examples (HBase, ZooKeeper, MongoDB default) vs AP (Cassandra, DynamoDB default)', 'cp', 'ap', 'cassandra', 'zookeeper'), kp('PACELC: latency vs consistency when no partition', 'pacelc', 'latency')],
    'The CAP theorem, by Eric Brewer, says that a distributed data store cannot simultaneously guarantee consistency, every read sees the latest write; availability, every request to a non-failing node gets a response; and partition tolerance, the system keeps working when the network splits nodes apart. Since network partitions will happen, the real choice is what to give up during a partition: a CP system, such as ZooKeeper, etcd or HBase, refuses some requests to stay consistent, while an AP system, such as Cassandra or DynamoDB by default, keeps answering, possibly with stale data, and reconciles later. PACELC extends it: even without partitions you trade latency against consistency.',
    'Where would you place a relational database with a single primary?', src),
  Q('nq-239', DB, 'M', 'concept', 'What do consistency, availability, and partition tolerance mean?',
    [kp('Consistency: every read returns the most recent write (linearizable)', 'most recent write', 'latest', 'linearizab*'), kp('Availability: every request to a healthy node gets a non-error response', 'every request', 'response', 'non error'), kp('Partition tolerance: system continues despite lost messages between nodes', 'network', 'partition', 'continue*', 'split'), kp('Different from ACID consistency', 'acid', 'different')],
    'In CAP, consistency means linearizability: all clients see the same data at the same time, and every read returns the most recent completed write, no matter which node answers; note this is different from the C in ACID, which is about constraints. Availability means every request received by a non-failing node returns a non-error response in reasonable time, even if the data might be stale. Partition tolerance means the system continues to operate even when the network drops or delays messages between nodes, splitting the cluster into groups that cannot talk to each other.',
    'Can a single-node database be "CA"?', src),
  Q('nq-240', DB, 'M', 'concept', 'How does Cassandra differ from a relational database?',
    [kp('Distributed wide-column store, masterless peer-to-peer ring', 'wide column', 'masterless', 'peer to peer', 'ring'), kp('Query-first data modelling with partition and clustering keys; denormalised tables per query', 'partition key', 'clustering key', 'query first', 'denormali*'), kp('No joins, limited ad hoc queries, no foreign keys', 'no join*', 'ad hoc', 'foreign key*'), kp('Tunable consistency, high write throughput, linear scalability', 'tunable consistency', 'write', 'linear*', 'scal*'), kp('Lightweight transactions only, not full ACID', 'lightweight transaction*', 'acid')],
    'Cassandra is a distributed, wide-column NoSQL database. Unlike a relational database with a primary server, it is masterless: every node is equal in a ring, data is partitioned by a hash of the partition key and replicated, so it scales linearly and survives node and even data centre failures. Data modelling is query-first: you design a table for each query, with a partition key that decides where data lives and clustering columns that sort data within the partition, duplicating data across tables instead of joining. There are no joins, foreign keys or arbitrary WHERE clauses, and only lightweight transactions, but it offers tunable consistency per query and very high write throughput thanks to its log-structured storage.',
    'What makes a good partition key in Cassandra?', src),
  Q('nq-241', DB, 'MS', 'concept', 'How does Cassandra distribute data across nodes?',
    [kp('Consistent hashing of the partition key into a token ring', 'consistent hashing', 'token*', 'ring', 'partitioner', 'murmur3'), kp('Virtual nodes (vnodes) spread ranges evenly', 'vnode*', 'virtual node*'), kp('Replication factor and strategy (NetworkTopologyStrategy, rack/DC aware)', 'replication factor', 'networktopologystrategy', 'rack', 'data center', 'datacenter'), kp('Any node acts as coordinator for a request', 'coordinator'), kp('Hot partitions if key is skewed', 'hot partition*', 'skew*', 'oversized partition*', 'hot or oversized')],
    'Cassandra uses consistent hashing. The partitioner, Murmur3 by default, hashes each row partition key into a token, and the token space is a ring divided among nodes; with virtual nodes each physical node owns many small token ranges, which balances data and makes adding nodes smoother. A row is stored on the node owning its token and replicated to further nodes according to the keyspace replication factor and strategy; NetworkTopologyStrategy places replicas on different racks and data centres. A client can contact any node, which acts as coordinator and forwards the request to the replicas. A badly chosen partition key, such as a date, creates hot or oversized partitions.',
    'What happens to data distribution when you add a node?', src),
  Q('nq-242', DB, 'SL', 'concept', 'What is the gossip protocol in Cassandra?',
    [kp('Peer-to-peer protocol for exchanging cluster state', 'peer to peer', 'peer-to-peer', 'cluster state', 'state'), kp('Each node gossips every second with up to three others', 'every second', 'three', 'random'), kp('Spreads membership, status, load, schema, token info', 'membership', 'status', 'up', 'down'), kp('Used with phi accrual failure detector; seed nodes bootstrap', 'failure detect*', 'phi', 'seed node*')],
    'Cassandra has no master that tracks the cluster, so nodes use a gossip protocol to share state. Every second each node exchanges messages with up to three other nodes chosen at random, sending what it knows about itself and others: whether they are up, their load, tokens, schema version and data centre. Versioned state means newer information wins, and it spreads to the whole cluster in a few rounds, like rumours. Nodes combine gossip with the phi accrual failure detector to mark peers as down. Seed nodes are known addresses used by new nodes to join and start gossiping. It is scalable and has no single point of failure.',
    'What are seed nodes, and are they special after startup?', src),
  Q('nq-243', DB, 'MS', 'concept', 'How does Cassandra support high availability?',
    [kp('Replication across nodes/racks/data centres, no single master', 'replication', 'replica*', 'masterless', 'data cent*'), kp('Tunable consistency (ONE, QUORUM, LOCAL_QUORUM, ALL)', 'quorum', 'local_quorum', 'tunable', 'consistency level*'), kp('Hinted handoff, read repair, anti-entropy repair', 'hinted handoff', 'read repair', 'repair'), kp('Writes accepted while some replicas are down', 'down', 'still accept*', 'writes')],
    'High availability comes from masterless replication: every partition is stored on several replicas, typically three per data centre, placed on different racks, and possibly in several data centres, and any node can coordinate requests, so there is no single point of failure. Clients choose a consistency level per request: with QUORUM or LOCAL_QUORUM, two out of three replicas must answer, so one node can be down without errors, and with ONE even more failures are tolerated. Missed writes are recovered through hinted handoff, where the coordinator stores hints for a down replica, read repair during reads, and regular anti-entropy repair with nodetool repair.',
    'Why do QUORUM reads plus QUORUM writes give strong consistency?', src),
  Q('nq-244', DB, 'SL', 'concept', 'What trade-offs exist between consistency, availability, and latency in distributed databases?',
    [kp('Strong consistency needs coordination across replicas -> higher latency, less availability', 'coordination', 'latency', 'replica*'), kp('Weaker consistency (eventual) gives lower latency and higher availability but stale reads', 'eventual', 'stale', 'lower latency'), kp('Quorum tuning: R + W > N', 'r + w > n', 'quorum', 'r+w'), kp('Multi-region: cross-region consensus is slow', 'multi region', 'cross region', 'geo', 'across regions'), kp('Choose per use case: payments vs likes', 'use case', 'payment*', 'per operation')],
    'Stronger consistency requires replicas to coordinate before answering: waiting for a quorum or a leader, consensus protocols like Raft or Paxos, which adds network round trips, so latency grows, especially across regions, and when replicas are unreachable the system must refuse requests, reducing availability. Weaker models, such as eventual consistency, answer from the nearest replica immediately, giving low latency and high availability but allowing stale or conflicting reads that must be resolved later. Many systems let you tune this: with N replicas, choosing reads R and writes W such that R plus W is greater than N gives read-your-writes consistency. Pick per operation: account balances and inventory need strong consistency; likes, feeds or analytics can be eventual.',
    'How does DynamoDB let you choose between strong and eventual reads?', src),
  Q('nq-245', DB, 'E', 'concept', 'What is database normalization?',
    [kp('Organising data to reduce redundancy and anomalies', 'redundan*', 'anomal*', 'duplicat*'), kp('Normal forms: 1NF atomic values, 2NF no partial dependency, 3NF no transitive dependency', '1nf', '2nf', '3nf', 'normal form*'), kp('Split into related tables with keys', 'split', 'tables', 'foreign key*', 'primary key*'), kp('BCNF; trade-off more joins', 'bcnf', 'join*')],
    'Normalisation is the process of structuring relational tables to remove redundant data and avoid insert, update and delete anomalies. You split data into related tables linked by keys, following normal forms. First normal form: atomic values and no repeating groups. Second normal form: every non-key column depends on the whole primary key, not part of a composite key. Third normal form: no transitive dependencies, non-key columns depend only on the key, so customer city belongs in the customer table, not in every order. BCNF is a stricter version of 3NF. The result is consistent data that is updated in one place, at the cost of more joins in queries.',
    'Can you give an example of an update anomaly?', src),
  Q('nq-246', DB, 'M', 'concept', 'What is database denormalization, and when would you use it?',
    [kp('Intentionally adding redundancy to speed up reads', 'redundan*', 'speed up', 'read*', 'intentional*'), kp('Avoid expensive joins/aggregations for read-heavy workloads', 'join*', 'read heavy', 'read-heavy', 'reporting'), kp('Examples: storing customer name on order, summary/materialised tables', 'materiali*', 'summary', 'precomputed', 'copy'), kp('Cost: more storage, write complexity, risk of inconsistency', 'storage', 'inconsisten*', 'write*'), kp('Common in NoSQL and data warehouses', 'nosql', 'warehouse', 'star schema')],
    'Denormalisation deliberately adds redundant data or precomputed results to make reads faster, after a normalised design has proven too slow. Examples: storing the product name and price on an order line so historical orders do not need joins and keep the price at the time of purchase; keeping an order_count column on customers; materialised views or summary tables for dashboards; star schemas in data warehouses; and query-shaped tables in Cassandra or embedded documents in MongoDB. You use it for read-heavy workloads, reporting and when joins at scale are too expensive. The cost is more storage, more complex writes, and the risk of copies getting out of sync, so you need triggers, events or batch jobs to keep them consistent.',
    'How would you keep denormalised data in sync?', src),
  Q('nq-247', DB, 'E', 'concept', 'How does normalization reduce data duplication?',
    [kp('Each fact stored once in the table where it belongs', 'stored once', 'one place', 'single place', 'only once'), kp('Other tables reference it by key', 'reference', 'foreign key*', 'key'), kp('Example: customer address in customers table, not in each order', 'customer', 'address', 'example'), kp('Updates happen in one place, avoiding anomalies', 'update*', 'anomal*', 'one place')],
    'Normalisation moves each fact into the table where it naturally belongs and stores it only once; other tables point to it with foreign keys instead of copying it. For example, instead of repeating a customer name, email and address on every order row, you keep them once in a customers table, and orders hold only customer_id. Repeating groups, like several phone numbers in one row, become rows in a separate table. As a result, changing the email is one update in one row, there is no risk of different orders showing different addresses for the same customer, and you can add a customer before they place an order.',
    'What problems would you see if customer details were copied into orders?', src),
  Q('nq-248', DB, 'E', 'concept', 'What is database indexing, and how does it improve query performance?',
    [kp('Separate data structure (usually B-tree) for fast lookup', 'b-tree', 'b tree', 'data structure', 'lookup'), kp('Avoids full table scans: O(log n) seeks', 'full table scan', 'scan', 'log n'), kp('Speeds WHERE, JOIN, ORDER BY on indexed columns', 'where', 'join', 'order by'), kp('Types: clustered/primary, secondary, composite, unique, covering', 'clustered', 'composite', 'unique', 'covering'), kp('Check with EXPLAIN plan', 'explain', 'execution plan')],
    'An index is an additional data structure, usually a B-tree, that keeps the values of one or more columns sorted, with pointers to the rows. Like a book index, it lets the database find matching rows by navigating the tree in logarithmic time instead of scanning the whole table, which matters hugely for large tables. It speeds up WHERE filters, joins on foreign keys, ORDER BY and GROUP BY on the indexed columns, and enforces uniqueness for unique indexes. Composite indexes cover several columns, with the leftmost prefix rule, and covering indexes contain all columns a query needs, so the table itself is not read. You verify usage with EXPLAIN or the execution plan.',
    'Why might the database ignore an index you created?', src),
  Q('nq-249', DB, 'M', 'concept', 'What are the disadvantages of adding too many indexes?',
    [kp('Slower writes: every insert/update/delete must update indexes', 'slower write*', 'insert', 'update', 'maintain*'), kp('Extra storage and memory/buffer cache pressure', 'storage', 'disk', 'memory', 'cache'), kp('Optimizer confusion / worse plans; redundant indexes', 'optimizer', 'plan*', 'redundant', 'duplicate'), kp('Lock contention and maintenance (rebuild, vacuum)', 'lock*', 'maintenance', 'rebuild', 'vacuum'), kp('Index only what queries need; monitor unused indexes', 'unused', 'monitor*', 'needed')],
    'Indexes are not free. Every insert, update and delete must also modify every affected index, so write-heavy tables become slower and generate more I/O and log volume. Each index takes disk space and competes for memory in the buffer cache, pushing out useful data. Many overlapping indexes can confuse the optimizer, which may pick a worse plan, and they increase lock contention and maintenance work such as rebuilds, statistics updates and vacuuming. So I index based on actual query patterns, prefer well-designed composite indexes over many single-column ones, remove redundant ones, and use the database statistics to find unused indexes.',
    'How would you find unused indexes in PostgreSQL or Oracle?', src),
  Q('nq-250', DB, 'M', 'concept', 'What is database partitioning?',
    [kp('Splitting a large table into smaller pieces within one database', 'split*', 'smaller', 'one database', 'same database'), kp('Horizontal (rows) vs vertical (columns) partitioning', 'horizontal', 'vertical'), kp('Strategies: range, list, hash', 'range', 'list', 'hash'), kp('Benefits: partition pruning, easier archiving/maintenance', 'pruning', 'archiv*', 'maintenance', 'drop partition'), kp('Transparent to queries; choose partition key carefully', 'transparent', 'partition key')],
    'Partitioning divides a large table into smaller physical pieces, partitions, while it still appears as one table to queries, usually within one database server. Horizontal partitioning splits rows, for example orders by month with range partitioning, by region with list partitioning, or evenly with hash partitioning; vertical partitioning splits columns, moving large or rarely used columns to another table. Benefits: queries that filter on the partition key only scan relevant partitions, partition pruning; indexes are smaller; and maintenance is easier, such as dropping an old month instead of deleting millions of rows. The partition key must match common query filters, otherwise queries scan all partitions.',
    'How would you partition an orders table with 2 billion rows?', src),
  Q('nq-251', DB, 'M', 'concept', 'What is database sharding?',
    [kp('Horizontal scaling: rows spread across multiple database servers', 'multiple server*', 'multiple database*', 'across', 'horizontal'), kp('Shard key determines placement (range, hash, directory)', 'shard key', 'hash', 'range', 'directory', 'lookup'), kp('Increases write/storage capacity beyond one machine', 'capacity', 'write*', 'one machine', 'single server'), kp('Challenges: cross-shard queries/transactions, rebalancing, hotspots', 'cross shard', 'cross-shard', 'rebalanc*', 'hotspot*', 'hot spot*'), kp('Built-in in MongoDB, Cassandra, Vitess, Citus', 'mongodb', 'cassandra', 'vitess', 'citus')],
    'Sharding is horizontal partitioning across separate database servers: each shard holds a subset of the rows, for example customers A to M on one server and N to Z on another, or more commonly by a hash of customer_id. This lets you scale storage and write throughput beyond a single machine. A shard key decides placement, using range, hash or a directory lookup service, and the application or a routing layer sends each query to the right shard. The difficulties are queries and transactions that span shards, rebalancing when adding shards, and hotspots when the key is skewed, so you choose a key that is used in most queries and spreads load evenly. MongoDB, Cassandra and DynamoDB shard natively; Vitess and Citus add it to MySQL and PostgreSQL.',
    'What makes a bad shard key?', src),
  Q('nq-252', DB, 'M', 'concept', 'What is the difference between partitioning and sharding?',
    [kp('Partitioning: pieces within one database instance', 'one database', 'single instance', 'same server', 'single database instance'), kp('Sharding: pieces on different servers/nodes', 'different server*', 'multiple server*', 'nodes'), kp('Partitioning mainly manageability/query pruning; sharding for scale-out capacity', 'manageab*', 'pruning', 'scale out', 'scale-out', 'capacity'), kp('Sharding adds distributed complexity', 'complexity', 'distributed'), kp('Sharding is a form of horizontal partitioning', 'form of', 'horizontal partitioning')],
    'Both split data into pieces by a key. Partitioning usually refers to splitting a table into partitions inside a single database instance; the database manages it transparently, and the benefits are query pruning, smaller indexes and easier maintenance, but the capacity is still limited to one server. Sharding is horizontal partitioning across multiple servers or nodes, each an independent database with its own CPU, memory and disk, so total capacity scales out, at the cost of distributed complexity: routing, cross-shard queries and transactions, and rebalancing. You often combine them: shard across servers, and partition by date within each shard.',
    'Would you shard or partition first, and why?', src),
  Q('nq-253', DB, 'SL', 'scenario', 'When would you use sharding in a large-scale application?',
    [kp('When a single node cannot handle data size or write throughput even after vertical scaling and replicas', 'single node', 'write throughput', 'data size', 'vertical scaling', 'read replica*'), kp('After optimising queries, indexes, caching and partitioning', 'optimi*', 'index*', 'cach*', 'partition*'), kp('Natural shard key exists (tenant, customer, region)', 'tenant', 'customer', 'region', 'natural key'), kp('Multi-tenant SaaS, data residency', 'multi tenant', 'saas', 'data residency', 'compliance'), kp('Accept cross-shard query limitations; consider managed distributed DBs', 'cross shard', 'limitation*', 'managed', 'distributed sql', 'shard natively')],
    'Sharding is a last resort because it adds lasting complexity. I would first optimise queries and indexes, add caching, read replicas for read scaling, vertical scaling, archiving old data and table partitioning. Sharding becomes the right choice when the data volume or the write throughput truly exceeds what one primary can handle, for example billions of rows growing fast or tens of thousands of writes per second, and when there is a natural shard key that most queries include, like tenant id in a multi-tenant SaaS, customer id or region, which can also satisfy data residency requirements. I would also consider databases that shard natively, like DynamoDB, Cassandra, CockroachDB or Citus, rather than building sharding into the application.',
    'How would you handle a report that needs data from all shards?', src),
  Q('nq-254', DB, 'M', 'concept', 'What is Amazon DynamoDB, and when would you use it?',
    [kp('Fully managed, serverless key-value/document NoSQL on AWS', 'managed', 'serverless', 'key value', 'key-value', 'nosql'), kp('Partition key (and sort key); single-digit millisecond latency at any scale', 'partition key', 'sort key', 'millisecond', 'scale'), kp('On-demand or provisioned capacity; GSIs/LSIs', 'on demand', 'on-demand', 'provisioned', 'gsi', 'secondary index*'), kp('Streams, TTL, global tables, transactions', 'streams', 'ttl', 'global tables', 'transaction*'), kp('Use for known access patterns at high scale; not for ad hoc joins/analytics', 'access pattern*', 'ad hoc', 'analytics', 'join*')],
    'DynamoDB is AWS fully managed, serverless NoSQL database for key-value and document data. You define a table with a partition key, and optionally a sort key, and DynamoDB distributes data automatically, giving single-digit millisecond latency at virtually any scale, with on-demand or provisioned capacity, automatic replication across availability zones, global tables for multi-region, TTL for expiry, DynamoDB Streams for change events, and ACID transactions over up to 100 items. Global and local secondary indexes support additional access patterns. I would use it for high-scale workloads with well-known access patterns, such as user sessions, shopping carts, IoT data, or serverless backends with Lambda, and avoid it where you need ad hoc queries, joins or complex reporting.',
    'What is single-table design in DynamoDB?', src),
  Q('nq-255', DB, 'EM', 'scenario', 'Which database technologies have you worked with, including Oracle, MongoDB, DynamoDB, and Cassandra?',
    [kp('Name databases with concrete project usage', 'project', 'used', 'worked'), kp('Relational: Oracle/PostgreSQL/MySQL with JPA/SQL tuning', 'oracle', 'postgres*', 'mysql', 'jpa', 'sql'), kp('NoSQL: MongoDB, DynamoDB, Cassandra use cases', 'mongodb', 'dynamodb', 'cassandra'), kp('Why each was chosen and lessons (indexes, modelling, consistency)', 'why', 'chose', 'lesson*', 'index*', 'model*'), kp('Be honest about depth', 'honest', 'exposure', 'depth')],
    'Answer with specifics rather than a list. For example: Oracle was our system of record for orders and billing; I wrote and tuned SQL and PL/SQL, read execution plans, added composite indexes and used JPA with Hibernate on top. MongoDB stored product catalogue documents whose attributes vary by category, where embedding variants in one document made reads fast. DynamoDB backed a serverless notification service with Lambda, designed around partition and sort keys and a GSI for lookups by status, with TTL to expire old records. Cassandra I used for high-volume event history queried by device and time. Explain why each was chosen, what you learned, such as query-first modelling or consistency levels, and be honest where your experience is lighter.',
    'Which of these would you pick for a new order management system?', src),
];
